from decimal import *
for trap in ['inexact','rounded','both']:
 with localcontext() as c:
  c.prec=3
  c.traps[Inexact]=trap in ['inexact','both']
  c.traps[Rounded]=trap in ['rounded','both']
  try: Decimal('1.234')+Decimal('0')
  except DecimalException as error:
   print(type(error).__name__,str(error),repr(error.args),c.flags.get(Inexact,False),c.flags.get(Rounded,False))
with localcontext() as c:
 c.prec=3;c.traps[Rounded]=True
 try: Decimal('1.2300')+Decimal('0')
 except Rounded as error:print(type(error).__name__,c.flags.get(Inexact,False),c.flags.get(Rounded,False))

from decimal import *
for precision in [3,28]:
 for mode in [ROUND_HALF_EVEN,ROUND_DOWN]:
  c=Context(prec=precision,rounding=mode)
  for index,value in enumerate([0.1,0.125,1.235,-0.0,1.0,0.25]+([0.0001] if precision==3 else [])):
   c.clear_flags();result=c.create_decimal_from_float(value)
   print(precision,mode,index,str(result),c.flags[Inexact],c.flags[Rounded],c.flags[FloatOperation])
   c.clear_flags();result=c.create_decimal(value)
   print(str(result),c.flags[Inexact],c.flags[Rounded],c.flags[FloatOperation])
print(Context(prec=3).create_decimal_from_float(2),Context(prec=3).create_decimal_from_float(True))

from decimal import *
c=Context(prec=3)
for text in ['1.'+'0'*80,'0.'+'0'*80,'10000000000000000000000000000','1E+28','000001.23400']:
 c.clear_flags();result=c.create_decimal(text)
 print(str(result),c.flags[Inexact],c.flags[Rounded])
c.clear_flags()
try: c.create_decimal('  +1.2500e+2  ')
except InvalidOperation as error:
 print(type(error).__name__,str(error),repr(error.args),c.flags[InvalidOperation])

from decimal import *
for precision in [1,3,28]:
 with localcontext() as c:
  c.prec=precision
  for left,right in [('1.234','1'),('-1.234','1'),('7.50','2'),('-0.00','2.0'),('1','-3'),('12','1')]:
   a=Decimal(left);b=Decimal(right)
   for name,operation in [('floor',lambda:a//b),('mod',lambda:a%b),('divmod',lambda:divmod(a,b))]:
    c.clear_flags()
    try: print(precision,left,right,name,str(operation()))
    except DecimalException as e: print(precision,left,right,name,type(e).__name__,str(e),repr(e.args))
    print(c.flags[Inexact],c.flags[Rounded],c.flags[InvalidOperation])

from decimal import *
for invalid,divide in [(True,True),(True,False),(False,True)]:
 with localcontext() as c:
  c.traps[InvalidOperation]=invalid;c.traps[DivisionByZero]=divide
  try: divmod(Decimal(1),Decimal(0))
  except DecimalException as e:
   print(invalid,divide,type(e).__name__,str(e),repr(e.args))
  print(c.flags[InvalidOperation],c.flags[DivisionByZero])

from decimal import *
for mode in [ROUND_HALF_EVEN,ROUND_FLOOR,ROUND_UP,ROUND_05UP]:
 with localcontext() as c:
  c.prec=1;c.rounding=mode
  for value in ['1.234','-1.234','1.251','-1.251']:
   c.clear_flags();result=Decimal(value)%Decimal(1)
   print(mode,value,str(result),c.flags[Inexact],c.flags[Rounded])
with localcontext() as c:
 c.prec=1;c.traps[Inexact]=True
 try: Decimal('1.234')%Decimal(1)
 except Inexact as e: print(type(e).__name__,repr(e.args),c.flags[Inexact],c.flags[Rounded])

from decimal import *
import operator
with localcontext() as c:
 c.prec=1
 print(operator.floordiv(Decimal('1.234'),Decimal(1)),operator.mod(Decimal('1.234'),Decimal(1)))
 for op in [lambda:Decimal(1)/Decimal(0),lambda:Decimal(0)/Decimal(0),lambda:Decimal(1)//Decimal(0),lambda:Decimal(1)%Decimal(0)]:
  c.clear_flags()
  try: op()
  except DecimalException as e: print(type(e).__name__,c.flags[InvalidOperation],c.flags[DivisionByZero])

from decimal import *
for precision in [3,28]:
 for mode in [ROUND_HALF_EVEN,ROUND_DOWN]:
  with localcontext() as c:
   c.prec=precision;c.rounding=mode
   for raw in ['1.25','1.234','2','-2','0.5']:
    for exponent in [-3,-1,0,1,2,5,10]:
     c.clear_flags();value=Decimal(raw)**exponent
     print(precision,mode,raw,exponent,str(value),c.flags[Inexact],c.flags[Rounded])

from decimal import *
for precision in [1,2,28]:
 with localcontext() as c:
  c.prec=precision
  for base,exponent,modulus in [(2,3,5),(-2,3,5),(-2,3,-5),(2,0,5),(0,0,5),(2,-1,5),(2,10,11),(2,10,7),(2,3,1),(2,10,0)]:
   c.clear_flags()
   try: print(precision,base,exponent,modulus,str(pow(Decimal(base),exponent,modulus)))
   except DecimalException as e:print(precision,base,exponent,modulus,type(e).__name__,str(e))
   print(c.flags[InvalidOperation],c.flags[Inexact],c.flags[Rounded])

from decimal import *
for mode in [ROUND_HALF_EVEN,ROUND_HALF_UP,ROUND_HALF_DOWN,ROUND_UP,ROUND_DOWN,ROUND_CEILING,ROUND_FLOOR,ROUND_05UP]:
 with localcontext() as c:
  c.rounding=mode
  for raw in ['2.55','-2.55','1.01','-1.01','5.00','-0.00','70000000000000000000000000000']:
   for quantum in ['1','0.1','1E+1']:
    c.clear_flags()
    try: result=str(Decimal(raw).quantize(Decimal(quantum)))
    except DecimalException as e: result=type(e).__name__
    print(mode,raw,quantum,result,c.flags[Inexact],c.flags[Rounded],c.flags[InvalidOperation])

from decimal import *
with localcontext() as c:
 c.prec=2;c.rounding=ROUND_FLOOR
 selected=Context(prec=3,rounding=ROUND_DOWN)
 for raw,quantum in [('1.239','0.01'),('99.99','0.1'),('1.230','0.01'),('0.00','1'),('-0.01','1')]:
  c.clear_flags();selected.clear_flags()
  try: result=str(Decimal(raw).quantize(Decimal(quantum),context=selected))
  except DecimalException as e: result=type(e).__name__+':'+repr(e.args)
  print(raw,result,selected.flags[Inexact],selected.flags[Rounded],selected.flags[InvalidOperation],any(c.flags.values()))
 c.clear_flags()
 try: Decimal('9.99').quantize(Decimal('0.1'),ROUND_UP)
 except InvalidOperation as e: print(type(e).__name__,repr(e.args),c.flags[InvalidOperation],c.flags[Inexact],c.flags[Rounded])

from decimal import *
with localcontext() as c:
 c.prec=1
 for mode in [ROUND_HALF_EVEN,ROUND_HALF_UP,ROUND_HALF_DOWN,ROUND_UP,ROUND_DOWN,ROUND_CEILING,ROUND_FLOOR,ROUND_05UP]:
  c.rounding=mode
  for raw in ['1.00','2.5','-2.5','-0.00','1E+2','-0E+4','123.45']:
   for name in ['to_integral_value','to_integral_exact','to_integral']:
    c.clear_flags();result=getattr(Decimal(raw),name)()
    print(mode,raw,name,str(result),c.flags[Inexact],c.flags[Rounded])

from decimal import *
with localcontext() as c:
 c.prec=3;c.traps[Inexact]=True;c.traps[Rounded]=True
 for method in ['to_integral_value','to_integral_exact','to_integral']:
  for raw in ['1.00','1.25','-0.00']:
   c.clear_flags()
   try: print(method,raw,str(getattr(Decimal(raw),method)()))
   except DecimalException as e: print(method,raw,type(e).__name__,repr(e.args))
   print(c.flags[Inexact],c.flags[Rounded])
 for raw in ['1.230','1.235']:
  c.clear_flags()
  try: print('quantize',str(Decimal(raw).quantize(Decimal('0.01'))))
  except DecimalException as e:print('quantize',type(e).__name__,repr(e.args))
  print(c.flags[Inexact],c.flags[Rounded])
 c.clear_flags();selected=Context(prec=1,rounding=ROUND_FLOOR)
 print(Decimal('123.5').to_integral_exact(ROUND_UP,selected),selected.flags[Inexact],selected.flags[Rounded],any(c.flags.values()))

from decimal import *
with localcontext() as c:
 c.prec=3;c.rounding=ROUND_DOWN
 for raw in ['1.239','-1.239','129','-0.00','1E+2']:
  for digits in [None,0,1,-1]:
   c.clear_flags()
   try: result=round(Decimal(raw)) if digits is None else round(Decimal(raw),digits)
   except DecimalException as e: print(raw,digits,type(e).__name__,repr(e.args))
   else: print(raw,digits,type(result).__name__,str(result))
   print(c.flags[Inexact],c.flags[Rounded],c.flags[InvalidOperation])
 c.traps[Inexact]=True
 try: round(Decimal('1.239'),2)
 except Inexact as e:print(type(e).__name__,repr(e.args),c.flags[Inexact],c.flags[Rounded])
 c.clear_flags()
 print(round(Decimal('1.9')),any(c.flags.values()))
